#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m, k, c, d;
    cin >> n >> m >> k >> c >> d;

    const int T = 99;
    const long long INF = 1LL << 60;
    const int C = 12;

    vector<vector<array<long long, 5>>> graph(50 * T + 2);
    auto addEdge = [&](int a, int b, long long cap=1, long long p=0) {
        graph[a].push_back({b, 0, cap, 0, p});
        graph[b].push_back({a, 0, 0, 0, -p});
    };

    int source = 0;
    int sink = n * T + 1;

    for (int i = 0; i < k; i++) {
        int a;
        cin >> a;
        addEdge(source, a);
    }

    for (int t = 0; t < T; t++) {
        addEdge(1 + t * n, sink, INF);
        if (t > 0) {
            for (int i = 1; i <= n; i++) {
                addEdge(i + (t - 1) * n, i + t * n, INF, c);
            }
        }
    }

    for (int i = 0; i < m; i++) {
        int a, b;
        cin >> a >> b;
        for (int j = 0; j < C; j++) {
            int cost = (j + 1) * (j + 1) - j * j;
            for (int t = 1; t < T; t++) {
                addEdge(a + (t - 1) * n, b + t * n, 1, cost * d + c);
                addEdge(b + (t - 1) * n, a + t * n, 1, cost * d + c);
            }
        }
    }

    long long totalFlow = 0, totalCost = 0;
    vector<long long> dist(graph.size()), potential(graph.size()), parent(graph.size());
    vector<int> parentEdge(graph.size());

    auto minCostFlowSolver = [&](int s, int t) {
        long long flow = 0, cost = 0;
        while (true) {
            fill(dist.begin(), dist.end(), LLONG_MAX);
            dist[s] = 0;
            priority_queue<pair<long long,int>, vector<pair<long long,int>>, greater<>> pq;
            pq.emplace(0, s);
            while (!pq.empty()) {
                auto [d, u] = pq.top(); pq.pop();
                if (d > dist[u]) continue;
                for (int i = 0; i < (int)graph[u].size(); i++) {
                    auto& e = graph[u][i];
                    if (e[2] > 0 && dist[u] + e[4] + potential[u] - potential[e[0]] < dist[e[0]]) {
                        dist[e[0]] = dist[u] + e[4] + potential[u] - potential[e[0]];
                        parent[e[0]] = u;
                        parentEdge[e[0]] = i;
                        pq.emplace(dist[e[0]], e[0]);
                    }
                }
            }
            if (dist[t] == LLONG_MAX) break;
            for (int i = 0; i < (int)graph.size(); i++) {
                if (dist[i] < LLONG_MAX) potential[i] += dist[i];
            }
            long long df = LLONG_MAX;
            for (int u = t; u != s; u = parent[u]) {
                auto& e = graph[parent[u]][parentEdge[u]];
                for (auto& e2 : graph[parent[u]]) {
                    if (e2[0] == u && e2[2] > 0) {
                        df = min(df, e2[2]);
                        break;
                    }
                }
            }
            for (int u = t; u != s; u = parent[u]) {
                auto& e = graph[parent[u]][parentEdge[u]];
                for (auto& e2 : graph[parent[u]]) {
                    if (e2[0] == u && e2[2] > 0) {
                        e2[2] -= df;
                        break;
                    }
                }
                for (auto& e2 : graph[u]) {
                    if (e2[0] == parent[u]) {
                        e2[2] += df;
                        cost += df * e2[4];
                        break;
                    }
                }
            }
            flow += df;
        }
        return make_pair(flow, cost);
    };

    auto result = minCostFlowSolver(source, sink);
    long long flow_value = result.first;
    long long total_price = result.second;

    if (flow_value != k) {
        cout << -1 << "\n";
    } else {
        cout << total_price << "\n";
    }

    return 0;
}
